import {normalizedPrompts,maskToPaths,promptTarget,insidePath} from './segment-model.js?v=20261024-seg1';
import {pathD} from './vision.js?v=20261024-seg1';
export function createTapUI(api){const $=id=>document.getElementById(id),compare=new URLSearchParams(location.search).has('segcompare');let engine='mediapipe',negative=false,newTool=false,serial=0,working=false,module=null,alternatives=[],timings={},message='',failed=false;
 try{if(localStorage.getItem('toolnest.segment.engine')==='sam')engine='sam';}catch{}
 const controls=document.createElement('div');controls.id='tapControls';controls.hidden=true;controls.innerHTML='<div class="tap-actions"><div class="tap-engines" role="group" aria-label="Segmentation engine"><button data-segment-engine="mediapipe" aria-pressed="true" title="MediaPipe MagicTouch">Quick</button><button data-segment-engine="sam" aria-pressed="false" title="SlimSAM">Precise</button></div><button id="tapNew" aria-pressed="false">New tool</button><button id="tapNegative" aria-pressed="false">Remove area</button><button id="tapUndo">Undo tap</button><button id="tapClear">Clear taps</button></div><div id="tapWork" hidden><progress id="tapProgress" aria-label="Model download"></progress><span id="tapStatus" role="status" aria-live="polite"></span><button id="tapCancel">Cancel</button><button id="tapRetry" hidden>Retry</button><button id="tapFallback" hidden>Smart edges</button></div><div id="tapCompare" hidden><span id="tapQuickTime"></span><span id="tapPreciseTime"></span></div>';
 document.querySelector('.canvas-top').after(controls);
 function status(text,error=false){message=text;failed=error;update();}
 function update(){const active=api.state().traceMethod==='tap';controls.hidden=!active;for(const b of controls.querySelectorAll('[data-segment-engine]')){b.setAttribute('aria-pressed',String(b.dataset.segmentEngine===engine));b.disabled=working;}$('tapNegative').setAttribute('aria-pressed',String(negative));$('tapNew').setAttribute('aria-pressed',String(newTool));$('tapNew').disabled=working;const tapped=api.state().tools[api.state().selected]?.tap;$('tapUndo').disabled=$('tapClear').disabled=working||!tapped;$('tapNegative').disabled=working;$('tapWork').hidden=!working&&!message;$('tapStatus').textContent=message;$('tapCancel').hidden=!working;$('tapRetry').hidden=!failed;$('tapFallback').hidden=!failed;$('tapCompare').hidden=!compare;
  if(compare)$('tapCompare').textContent=['mediapipe','sam'].map(e=>{const t=timings[e];return `${e==='sam'?'Precise':'Quick'}${t?`: load ${Math.round(t.loadMs)} ms · embedding ${Math.round(t.embeddingMs)} ms · tap ${Math.round(t.tapMs)} ms · ${t.device}`:': —'}`;}).join('\n');}
 function progress(p){if(p.phase==='download'){message=`Downloading ${p.file||'model'}${p.loaded?` · ${(p.loaded/1e6).toFixed(1)}${p.total?' / '+(p.total/1e6).toFixed(1):''} MB`:''}`;if(p.total){$('tapProgress').max=p.total;$('tapProgress').value=p.loaded||0;}else $('tapProgress').removeAttribute('value');}else{message={runtime:'Loading runtime…',initializing:'Preparing model…',embedding:'Preparing photo…'}[p.phase]||'Tracing…';$('tapProgress').removeAttribute('value');}update();}
 async function ready(e=engine,expected=serial){module||=await import('./segment.js?v=20261024-seg1');if(expected!==serial)throw new DOMException('Cancelled','AbortError');return module.loadSegmenter(e,progress);}
 function invalidate(){const cancel=working;serial++;working=false;alternatives=[];timings={};message='';failed=false;if(cancel)for(const e of ['mediapipe','sam'])module?.cancelSegmenter(e);update();}
 async function activate(){if(api.state().traceMethod!=='tap'){invalidate();return;}api.overlay();update();if(!api.photo())return status('Choose the original photo to add taps.');const job=++serial;working=true;status('Loading model…');try{await ready();if(job===serial)status('');}catch(e){if(job===serial&&e.name!=='AbortError')status(e.message,true);}finally{if(job===serial){working=false;update();}}}
 async function run(points,index){if(working)return;if(index<0&&api.state().tools.length>=50)return api.toast('A Trace project can contain up to 50 tools.');const rect=api.photo();if(!rect)return status('Choose the original photo to add taps.');if(points.length>64)return api.toast('Use up to 64 taps per tool.');let normalized;try{normalized=normalizedPrompts(points,rect);}catch(e){return api.toast(e.message);}const before=api.snapshot(),job=++serial;working=true;alternatives=[];status('Tracing…');
  try{const segmenter=await ready(),result=await segmenter.segment(rect,normalized),paths=maskToPaths(result,rect,api.state().paper,{minArea:api.state().minToolArea,points});if(job!==serial||api.photo()!==rect||api.snapshot()!==before)return;if(!paths.length)throw Error('No complete tool found. Tap farther inside the tool or try the other engine.');const s=api.state();api.remember();const tool={...(s.tools[index]||{name:`Tool ${s.tools.length+1}`}),points:paths[0],tap:{engine,points}};if(index<0){s.tools.push(tool);s.selected=s.tools.length-1;}else{s.tools[index]=tool;s.selected=index;}api.commit();timings[engine]=result.timing;
   if(compare){alternatives.push({engine,paths});const other=engine==='sam'?'mediapipe':'sam';try{const second=await ready(other),result=await second.segment(rect,normalized);if(job!==serial||api.photo()!==rect)return;const paths=maskToPaths(result,rect,s.paper,{minArea:s.minToolArea,points});alternatives.push({engine:other,paths});timings[other]=result.timing;}catch(e){if(job===serial)message=`Comparison: ${e.message}`;}}
   if(job===serial){failed=false;if(!message.startsWith('Comparison:'))message='';api.draw();}
  }catch(e){if(job===serial&&e.name!=='AbortError')status(e.message,true);}finally{if(job===serial){working=false;update();}}
 }
 async function tap(p){if(working)return api.toast('Wait for tracing, or cancel.');const s=api.state();let index=newTool?-1:promptTarget(s.tools,p,s.selected,negative);if(index<0&&!negative&&!newTool)index=s.tools.findIndex(t=>insidePath(p,t.points));if(index<0&&!negative&&!newTool&&s.tools[s.selected]?.tap)index=s.selected;if(negative&&index<0)return api.toast('Select a tap-traced tool first.');const points=[...(s.tools[index]?.tap?.points||[]),{...p,label:negative?0:1}];await run(points,index);newTool=false;update();}
 $('tapNew').onclick=()=>{newTool=!newTool;negative=false;update();};$('tapNegative').onclick=()=>{negative=!negative;newTool=false;update();};$('tapCancel').onclick=()=>{invalidate();status('Cancelled',true);};$('tapRetry').onclick=activate;$('tapFallback').onclick=()=>api.method('edges');
 for(const b of controls.querySelectorAll('[data-segment-engine]'))b.onclick=async()=>{invalidate();engine=b.dataset.segmentEngine;try{localStorage.setItem('toolnest.segment.engine',engine);}catch{}const s=api.state(),pending=s.tools.map((t,i)=>t.tap?{i,points:t.tap.points}:null).filter(Boolean);await activate();if(failed)return;for(const item of pending){if(s.traceMethod!=='tap'||engine!==b.dataset.segmentEngine)break;await run(item.points,item.i);}};
 $('tapUndo').onclick=()=>{const s=api.state(),tool=s.tools[s.selected];if(!tool?.tap)return;const points=tool.tap.points.slice(0,-1);if(points.some(p=>p.label===1))run(points,s.selected);else clear();};
 function clear(){const s=api.state();if(!s.tools[s.selected]?.tap)return;invalidate();api.remember();s.tools.splice(s.selected,1);s.fingers=s.fingers.filter(f=>f.tool!==s.selected).map(f=>({...f,tool:f.tool>s.selected?f.tool-1:f.tool}));s.selected=Math.max(0,s.selected-1);api.commit();}
 $('tapClear').onclick=clear;
 function draw(add){if(api.state().traceMethod!=='tap')return;const radius=4/Math.max(.01,Math.abs($('editor').getScreenCTM()?.a||1));for(const {engine,paths} of alternatives)paths.forEach((p,i)=>add(`tap-compare-${engine}-${i}`,'path',{d:pathD(p),class:`tap-outline tap-${engine}`,'pointer-events':'none'}));const tool=api.state().tools[api.state().selected];for(const [i,p] of (tool?.tap?.points||[]).entries())add('tap-point-'+i,'circle',{cx:p.x,cy:p.y,r:radius,class:p.label?'tap-positive':'tap-negative','pointer-events':'none'});}
 return {tap,activate,invalidate,update,draw,get active(){return api.state().traceMethod==='tap';}};
}
